        sds dsl = sdsempty();
        listRewind(s->patterns, &li);
        while ((ln = listNext(&li))) {
            keyPattern *thispat = (keyPattern *)listNodeValue(ln);
            if (ln != listFirst(s->patterns)) dsl = sdscat(dsl, " ");
