        }
        addReplyBulkSds(c, dsl);
    }

    /* Pub/sub patterns */
    addReplyBulkCString(c, "channels");
    if (s->flags & SELECTOR_FLAG_ALLCHANNELS) {
        addReplyBulkCBuffer(c, "&*", 2);
    } else {
        sds dsl = sdsempty();
        listRewind(s->channels, &li);
        while ((ln = listNext(&li))) {
